(function() {
  const paaElement = element;
  const parent = paaElement.parentNode;
  if (!parent) return;

  // Find the first web result (data-rpos="2")
  const firstResult = parent.querySelector('div.A6K0A[data-rpos="2"]');
  if (!firstResult) return;

  // Insert PAA right after the first result
  const nextSibling = firstResult.nextSibling;
  if (nextSibling === paaElement) {
    // Already in correct position
    return;
  }

  parent.insertBefore(paaElement, nextSibling);
})();
